add_action('wp_footer', function () {
    ?>
    <script id="harmat-legacy-visible-text-cleanup">
    (function () {
      function fixNode(node) {
        if (!node || node.nodeType !== Node.TEXT_NODE) return;
        var value = node.nodeValue || '';
        var next = value
          .replace(/Harmatliget lakópark/gi, 'Harmat 22 Lakópark')
          .replace(/Harmatliget/gi, 'Harmat 22')
          .replace(/Gipsz\s*Jakab/gi, 'Harmat 22 értékesítés')
          .replace(/012[\s-]*888[\s-]*2222/g, '+36-30-641-03-58')
          .replace(/agent\.name@example\.com/gi, 'ertekesites@harmat22.hu')
          .replace(/06\s*\(1\)\s*220\s*[–-]\s*0677/g, '+36-30-641-03-58')
          .replace(/modumkft@gmail\.com/gi, 'ertekesites@harmat22.hu');
        if (next !== value) node.nodeValue = next;
      }
      var walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
      var nodes = [];
      while (walker.nextNode()) nodes.push(walker.currentNode);
      nodes.forEach(fixNode);
      document.querySelectorAll('a[href^="mailto:modumkft@gmail.com"],a[href^="mailto:agent.name@example.com"]').forEach(function (a) {
        a.href = 'mailto:ertekesites@harmat22.hu';
      });
    })();
